function validate([code]) {
  if (typeof code !== 'string' || code.length < 1 || code.length > 500) return 'code needs 1 to 500 characters.';
  if (!/^[A-Za-z0-9<>\/!\[\]. ]+$/.test(code)) return "code may contain only letters, digits, '<', '>', '/', '!', '[', ']', '.' and spaces.";
  return null;
}

