function isValid(code) {
  const stack = [];
  let i = 0;
  while (i < code.length) {
    if (i > 0 && stack.length === 0) {
      return false;
    }
    if (stack.length > 0 && code.startsWith('<![CDATA[', i)) {
      const end = code.indexOf(']]>', i + 9);
      if (end < 0) {
        return false;
      }
      i = end + 3;
    } else if (code[i] === '<') {
      const closing = code[i + 1] === '/';
      const start = closing ? i + 2 : i + 1;
      const end = code.indexOf('>', start);
      if (end < 0) {
        return false;
      }
      const name = code.slice(start, end);
      if (!/^[A-Z]{1,9}$/.test(name)) {
        return false;
      }
      if (closing) {
        if (stack.pop() !== name) {
          return false;
        }
      } else {
        stack.push(name);
      }
      i = end + 1;
    } else if (stack.length === 0) {
      return false;
    } else {
      i++;
    }
  }
  return stack.length === 0;
}

