function isValid(code) {
  // Hide every cdata section, then keep collapsing innermost valid tags until one root remains.
  let text = code.replace(/<!\[CDATA\[.*?\]\]>/g, 'c');
  for (;;) {
    const next = text.replace(/<([A-Z]{1,9})>[^<]*<\/\1>/g, 't');
    if (next === text) break;
    text = next;
  }
  return text === 't';
}

