function generate(rand, size) {
  const pick = chars => chars[Math.floor(rand() * chars.length)];
  const tagName = () => Array.from({ length: 1 + Math.floor(rand() * (rand() < 0.15 ? 9 : 3)) }, () => pick('ABCXYZ')).join('');
  const text = () => Array.from({ length: Math.floor(rand() * 5) }, () => pick('ab Z9.!/[]>')).join('');
  const cdata = () => '<![CDATA[' + Array.from({ length: Math.floor(rand() * 5) }, () => pick('<>/!A]][ ')).join('') + ']]>';
  const node = (target, depth) => {
    const name = tagName();
    let content = '';
    while (content.length < target) {
      const r = rand();
      if (r < 0.4 || depth >= 4) content += text() || 'x';
      else if (r < 0.6) content += cdata();
      else content += node(Math.floor((target - content.length) * rand()), depth + 1);
    }
    return '<' + name + '>' + content + '</' + name + '>';
  };
  const all = 'aZ9<>/![]. ';
  for (;;) {
    let code = node(size === 'large' ? 380 + Math.floor(rand() * 80) : Math.floor(rand() * 20), 0);
    if (rand() < 0.5) {
      const at = Math.floor(rand() * code.length), kind = Math.floor(rand() * 6);
      if (kind === 0) code = code.slice(0, at) + pick(all) + code.slice(at + 1);
      else if (kind === 1) code = code.slice(0, at) + pick(all) + code.slice(at);
      else if (kind === 2 && code.length > 1) code = code.slice(0, at) + code.slice(at + 1);
      else if (kind === 3) code = code + pick(['<A></A>', ' ', '>', '<![CDATA[x]]>']);
      else if (kind === 4) code = code.replace(/<\/[A-Z]/, m => m.slice(0, 2) + (m[2] === 'A' ? 'B' : 'A'));
      else code = code.replace(/<([A-Z]+)>/, (m, name) => '<' + name.toLowerCase() + '>');
    }
    if (code.length >= 1 && code.length <= 500) return [code];
  }
}
